function detectLang() {
  try {
    var stored = localStorage.getItem("qvq_lang");
    if (stored && I18N[stored]) return stored;
    var nav = (navigator.language || "zh-CN").toLowerCase();
    if (nav.startsWith("zh")) return nav.includes("tw") || nav.includes("hk") ? "zh-TW" : "zh-CN";
    for (var k of Object.keys(I18N)) if (k !== "zh-CN" && nav.startsWith(k.split("-")[0].toLowerCase())) return k;
  } catch (e) {}
  return "zh-CN";
}

